callGraph.callee:
mediaPurposes
          .map((p) => {
            const slots = expandPolicyRequired(p.required)
              .map(
                (mimes, i) =>
                  `slot ${i}: ${
                    mimes.length > 1
                      ? `one of [${mimes.join(", ")}]`
                      : mimes[0]
                  }`,
              )
              .join("; ");
            const caps = Object.entries(p.maxBytes)
              .map(([m, b]) => `${m}=${b}`)
              .join(", ");
            return `  • ${p.name} upload rules — ${slots}; choose exactly one mime per slot from this live policy; maxBytes: ${caps}`;
          })
          .join
